PSM_DataSchemaVersion = 1

-- Models Data Export
-- Generated automatically
-- Structure-of-arrays layout, backed by a dense npcId<->index backbone.
-- ModelsData.Index[npcId] = denseIndex; ModelsData.NpcId[denseIndex] = npcId.
-- Every per-record column (Name, DisplayIds, UiMapId, FamilyId,
-- ExpansionId, ReactA, ReactH, ClassificationId, NameKeeper, Taming) is
-- ModelsData.<Column>[denseIndex] = value.
-- Families/Expansions/Classifications are separate lookups keyed by their
-- own internal-only IDs (NOT denseIndex, NOT stable across regenerations --
-- resolve display strings through them, never persist the raw ID).
-- UiMapNames is also a separate lookup, but keyed by uiMapId directly (via
-- the UiMapId column above) -- Blizzard's own stable zone ID, not one of
-- ours, safe to treat as stable.

